#!/usr/bin/env python3
"""Bind Ice Arrow's packet freeze conversion and shared cold/freeze/poison order."""
import argparse,hashlib,json
from review_weapon_event_order import ROOT,STAGE,function
from review_magic_arrow_contact import record as parent

def record(check=False):
    parent(True);tree=json.loads((STAGE/'d2moo-source-tree.json').read_text());path='source/D2Game/src/MISSILES/MissMode.cpp';raw=(STAGE/'d2moo-pinned-source'/path).read_bytes();assert hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()==next(x['sha']for x in tree['tree']if x['path']==path);name='MISSMODE_SrvDmg02_IceArrow_RoyalStrikeChaos';body=function(raw.decode(),name);assert 'pDamage->dwFrzLen =' in body and 'pDamage->dwColdLen = 0;' in body
    events=function((STAGE/'d2moo-pinned-source/source/D2Game/src/UNIT/SUnitDmg.cpp').read_text(),'SUNITDMG_ExecuteEvents');assert events.index('SUNITDMG_ApplyColdState(')<events.index('SUNITDMG_ApplyFreezeState(')<events.index('SUNITDMG_ApplyPoisonDamage(')
    cached=ROOT/'tools/reference/d2r-named-equipment';manifest=json.loads((cached/'sources.json').read_text());source=cached/'json/missiles.json';sha=hashlib.sha256(source.read_bytes()).hexdigest();assert sha==manifest['files']['json/missiles.json']['sha256'];row=json.loads(source.read_text())['icearrow'];runtime=next(r['fields']for r in json.loads((ROOT/'data/Sanctuary/Balance/necromancer-summons.json').read_text())if r['key']=='icearrow');fields={k:row.get(k,0)for k in ('GetHit','HitClass','pSrvDoFunc','pSrvDmgFunc','ToHit','NextHit','NextDelay','Range','Vel','dParam1')};assert fields==dict(GetHit=1,HitClass=0,pSrvDoFunc=1,pSrvDmgFunc=2,ToHit=1,NextHit=0,NextDelay=0,Range=40,Vel=24,dParam1=100);assert all(runtime.get(k,0)==v for k,v in fields.items())
    result=dict(referenceVersion='3.3.93847',legacyCommit=tree['sha'],damageFunction=dict(path=path,name=name,sha256=hashlib.sha256(body.encode()).hexdigest()),sharedImpactReviewSha256=hashlib.sha256((ROOT/'tools/reference/magic-arrow-contact-source-review.json').read_bytes()).hexdigest(),currentMissilesSha256=sha,missileFields=fields,established=['Damage callback2 writes100percent captured cold length into packet freeze length and clears ordinary cold length before missile events. Physical/elemental/poison damage remains.','Reuse the existing Dragon cold/freeze length adapter for resistance/item mitigation and existing native elite chill mapping. Project the chosen mitigated lengths into the actual player packet,including existing Dragon contacts.','The shared source event body commits cold,freeze,poison after HP and before kill/return. Use existing qualified status receivers,freeze corpse eligibility and owner/difficulty/thaw behavior.','Preserve existing collector,cost,quantity,flight,PMH,armor and proc stream rules. No missile attack event is invented.'],remaining=['Modern AR/provider/owner/stat/RNG/attack and exceptional uninterruptable/hireling mapping remain unverified.','Ordinary nonfreeze cold corpse shatter is still unsupported;Ice Arrow retains the existing explicit frozen-corpse eligibility mask.','This is scoped source/native qualification,not full current executable,class/client or named-item admission.'])
    p=ROOT/'tools/reference/ice-arrow-contact-source-review.json';encoded=json.dumps(result,indent=2)+'\n'
    if check:assert p.read_text()==encoded
    else:p.write_text(encoded)
    print('Ice Arrow packet freeze conversion and cold/freeze/poison order bound;existing adapter limits retained.')
if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--check',action='store_true');record(p.parse_args().check)
